using RemoteAdmin.Shared;
namespace RemoteAdmin.Client;
internal sealed class ConnectionProperties : Form {
 public Bookmark? Result {get;private set;}
 public ConnectionProperties(Bookmark? entry,string currentFolder,IEnumerable<string> folders){
  ViewerUi.Dialog(this,entry==null?"Новое соединение":"Свойства соединения",new Size(620,395));var buttons=ViewerUi.Buttons();var cancel=ViewerUi.Button("Отмена",(_,_)=>DialogResult=DialogResult.Cancel);var ok=ViewerUi.Button("OK",(_,_)=>{});buttons.Controls.Add(cancel);buttons.Controls.Add(ok);
  var root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=1,Padding=new Padding(12)};root.ColumnStyles.Add(new(SizeType.Absolute,185));root.ColumnStyles.Add(new(SizeType.Percent,100));var tree=new TreeView{Dock=DockStyle.Fill,HideSelection=false};tree.Nodes.Add("Общие настройки");tree.Nodes.Add("Безопасность TLS");root.Controls.Add(tree,0,0);var pages=new Panel{Dock=DockStyle.Fill,Padding=new Padding(12,0,0,0)};root.Controls.Add(pages,1,0);
  var general=ViewerUi.Stack();general.Dock=DockStyle.Fill;var name=new TextBox{Text=entry?.Name??""};var host=new TextBox{Text=entry?.Host??""};var port=new NumericUpDown{Minimum=1,Maximum=65535,Value=entry?.Port??4899};var defaultPort=new CheckBox{Text="По умолчанию",AutoSize=true,Checked=port.Value==4899};defaultPort.CheckedChanged+=(_,_)=>{port.Enabled=!defaultPort.Checked;if(defaultPort.Checked)port.Value=4899;};port.Enabled=!defaultPort.Checked;
  var folder=new ComboBox{DropDownStyle=ComboBoxStyle.DropDown,Text=entry?.Folder??currentFolder};folder.Items.Add("");folder.Items.AddRange(folders.Distinct().Cast<object>().ToArray());ViewerUi.Add(general,ViewerUi.Field("Имя записи:",name));ViewerUi.Add(general,ViewerUi.Field("IP-адрес или DNS-имя:",host));ViewerUi.Add(general,ViewerUi.Field("Порт:",port));ViewerUi.Add(general,defaultPort);ViewerUi.Add(general,ViewerUi.Field("Папка:",folder));
  var security=ViewerUi.Stack();security.Dock=DockStyle.Fill;security.Visible=false;var fingerprint=new TextBox{Text=entry?.Fingerprint??"",Multiline=true,Height=65,Font=new Font("Consolas",9)};ViewerUi.Add(security,ViewerUi.Field("SHA-256 сервера (необязательно):",fingerprint));ViewerUi.Add(security,ViewerUi.Label("При первом входе ключ можно сверить и подтвердить.\nЛогин и пароль запрашивает сервер; пароль\nв адресной книге не сохраняется."));pages.Controls.Add(security);pages.Controls.Add(general);tree.AfterSelect+=(_,e)=>{general.Visible=e.Node!.Index==0;security.Visible=!general.Visible;};tree.SelectedNode=tree.Nodes[0];Controls.Add(root);Controls.Add(buttons);AcceptButton=ok;CancelButton=cancel;
  ok.Click+=(_,_)=>{var pin=fingerprint.Text.Replace(" ","").Replace(":","").Trim().ToUpperInvariant();if(string.IsNullOrWhiteSpace(host.Text)||host.Text.Length>255){MessageBox.Show(this,"Укажите IP-адрес или DNS-имя сервера.");return;}if(pin.Length!=0&&(pin.Length!=64||!pin.All(Uri.IsHexDigit))){MessageBox.Show(this,"Ключ должен содержать 64 hex-символа.");return;}if(folder.Text.Length>500){MessageBox.Show(this,"Слишком длинное имя папки.");return;}Result=new(string.IsNullOrWhiteSpace(name.Text)?host.Text.Trim():name.Text.Trim(),host.Text.Trim(),(int)port.Value,pin,folder.Text.Trim('/'));DialogResult=DialogResult.OK;};
 }
}
